mapper.select:
SELECT * FROM ( SELECT R.REPORT_NO AS "reportNo", R.TARGET_TYPE AS "targetType", R.TARGET_NO AS "targetNo", R.REPORT_TYPE AS "reportType", R.DETAIL_REASON AS "detailReason", R.STATUS AS "status", R.RESULT AS "result", TO_CHAR(R.CREATED_AT, 'YYYY-MM-DD HH24:MI') AS "createdAt", TO_CHAR(R.UPDATED_AT, 'YYYY-MM-DD HH24:MI') AS "updatedAt", M.NICKNAME AS "reporterNickname", /* 신고 대상 제목 — targetType별 서브쿼리로 원본 제목 조회 */ CASE R.TARGET_TYPE WHEN 'FREEBOARD' THEN (SELECT B.TITLE FROM BOARD B WHERE B.BOARD_NO = R.TARGET_NO) WHEN 'COMPANION' THEN (SELECT CB.TITLE FROM COMPANION_BOARD CB WHERE CB.COMPANION_NO = R.TARGET_NO) WHEN 'REVIEW' THEN (SELECT CR.TITLE FROM COMPANION_REVIEW CR WHERE CR.REVIEW_NO = R.TARGET_NO) WHEN 'COMMENT' THEN (SELECT DBMS_LOB.SUBSTR(C.CONTENT, 50, 1) FROM COMMENT_TBL C WHERE C.COMMENT_NO = R.TARGET_NO) END AS "targetTitle", ROW_NUMBER() OVER (ORDER BY R.CREATED_AT DESC) AS RN FROM CONTENT_REPORT R JOIN MEMBER M ON R.MEMBER_NO = M.MEMBER_NO WHERE 1=1
AND R.STATUS = #{status}
AND R.TARGET_TYPE = #{targetType}
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

SELECT COUNT(*)
FROM CONTENT_REPORT R
WHERE 1=1

    AND R.STATUS = #{status}


    AND R.TARGET_TYPE = #{targetType}

SELECT MEMBER_NO
FROM MEMBER_VERIFICATION
WHERE VERIFICATION_NO = #{verificationNo}

SELECT * FROM ( SELECT R.REVIEW_NO AS "reviewNo", R.RATING AS "rating", DBMS_LOB.SUBSTR(R.CONTENT, 100, 1) AS "content", R.STATUS AS "status", TO_CHAR(R.CREATED_AT, 'YYYY-MM-DD') AS "createdAt", M.NICKNAME AS "authorNickname", M.MEMBER_NO AS "memberNo", A.NAME AS "accommodationName", A.ACCOMMODATION_NO AS "accommodationNo", ROW_NUMBER() OVER (ORDER BY R.CREATED_AT DESC) AS RN FROM ACCOMMODATION_REVIEW R JOIN MEMBER M ON R.MEMBER_NO = M.MEMBER_NO JOIN ACCOMMODATION A ON R.ACCOMMODATION_NO = A.ACCOMMODATION_NO WHERE R.STATUS != 'D'
AND (A.NAME LIKE '%' || #{search} || '%' OR M.NICKNAME LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

